-- check for listed-only sibling keys mentioned in resolve_entity note (none reported) and get top assets by phase for both conditions
SELECT 'NSCLC' AS grp, p.max_phase_ever, count(*) AS n_assets
FROM v_programs p WHERE p.condition_key='D002289' GROUP BY 1 ORDER BY 1 DESC;

WITH n AS (
  SELECT condition_key, note FROM (SELECT 'D002289' AS condition_key, '' AS note) 
)
SELECT display_name, condition_key, n_trials FROM v_conditions WHERE condition_key IN ('D002289','D008175');

-- check for listed-only sibling keys mentioned in resolve_entity note (none reported) and get top assets by phase for both conditions
SELECT 'NSCLC' AS grp, p.max_phase_ever, count(*) AS n_assets
FROM v_programs p WHERE p.condition_key='D002289' GROUP BY 1 ORDER BY 1 DESC;

SELECT p.max_phase_ever, count(*) AS n_assets
FROM v_programs p WHERE p.condition_key='D002289'
GROUP BY p.max_phase_ever ORDER BY p.max_phase_ever DESC NULLS LAST;

SELECT p.max_phase_ever, count(*) AS n_assets
FROM v_programs p WHERE p.condition_key='D008175'
GROUP BY p.max_phase_ever ORDER BY p.max_phase_ever DESC NULLS LAST;

